// table Tally — TABLE-wire storage: relocatable, bounded, defaults in the
// member initializers (docs/SPEC-TABLES.md)
struct Tally {
    int32_t hits = 0;
};

// table Marker — TABLE-wire storage: relocatable, bounded, defaults in the
// member initializers (docs/SPEC-TABLES.md)
struct Marker {
    char label[8 + 1] = {}; // string(8): max length, used length beside it
    int32_t label_length = 0;
    TableRef note; // *Tally — null until assigned
};

// ---- prefill: the declared defaults, in place (docs/SPEC-TABLES.md) ----

inline void TallyReset( Tally & value );
inline void MarkerReset( Marker & value );

inline void TallyReset( Tally & value )
{
    value.hits = 0;
}

inline void MarkerReset( Marker & value )
{
    memset( value.label, 0, sizeof( value.label ) );
    value.label_length = 0;
    value.note.value = 0; // *Tally — null
}

inline int64_t TallyMeasureMessageBody( int64_t at, const Tally & value );
inline bool TallySaveMessageBody( TableBitWriter & w, const Tally & value );
inline bool TallyLoadMessageBody( TableBitReader & r, const TableVocabulary & vocabulary, TableReport * report, int64_t index_bits, Tally & value );
template <typename Ctx> inline int64_t MarkerMeasureMessageBody( const Ctx & ctx, const TableNumbering & numbering, int64_t index_bits, int64_t at, const Marker & value );
