// ---- the numbering's bridge to each member's codec (docs/SPEC-TABLES.md §3.1) ----

template <typename Ctx> inline int64_t TableNodeMeasure( const Ctx &, const TableNumbering &, TableIds & ids, const Tally & value ) { return TallyMeasureBody( ids, value ); }
template <typename Ctx> inline bool TableNodeSave( const Ctx &, const TableNumbering &, TableWriter & w, TableIds & ids, const Tally & value ) { return TallySaveBody( w, ids, value ); }
